# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def _pupil(last, first):
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            _pupil("Halloway", "Juno"),
            _pupil("Dunmere", "Piet"),
            _pupil("Adler", "Sam")
        ]

    def test_rows_sorted_by_last_name(self):
        self.assertEqual(
            seat_rows(self.pupils, 2),
            ["Row 1: Adler, Sam | Dunmere, Piet",
             "Row 2: Halloway, Juno"]
        )

    def test_single_row(self):
        lines = seat_rows(self.pupils, 5)
        self.assertEqual(len(lines), 1)

    def test_bad_seat_counts(self):
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seat_rows(self.pupils, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
